        nplChart: { type: 'line', data: { labels: [], datasets: [{ label: t('chart_npl_label'), data: [], borderColor: '#e74c3c', backgroundColor: 'rgba(231,76,60,0.1)', borderWidth: 3, fill: true, tension: 0.3, pointBackgroundColor: '#e74c3c', pointRadius: 5 }] }, options: { responsive: true, maintainAspectRatio: false, plugins: { title: { display: true, text: t('chart_npl_title') } }, scales: { y: { beginAtZero: false, suggestedMin: 0, suggestedMax: 10 } } } }
