    getChartData(state) {
      var labels = state.domainState.nimHistory.map(function(_, i) { return 'R' + (i + 1); });
      return {
        nimChart: { labels: labels, datasets: [{ data: state.domainState.nimHistory, label: window.mySimulation.t('col_nim') }] },
        nplChart: { labels: labels, datasets: [{ data: state.domainState.nplHistory, label: window.mySimulation.t('chart_npl_label') }] }
      };
    }

    // Composite (0-1000) of the final verdict, read from domainState; shared with the per-round platform score.
    _composite(ds) {
      var customerGrowth = ((ds.customers - 12800) / 12800) * 100;
      var nimScore = Math.min(1, Math.max(0, (ds.nim - 3) / 4));
      var nplScore = Math.min(1, Math.max(0, (8 - ds.nplRatio) / 6));
      var custScore = Math.min(1, Math.max(0, customerGrowth / 25));
      var roaScore = Math.min(1, Math.max(0, (ds.roa - 0.5) / 3));
      var conductScore = ds.conductRiskScore / 100;
      return Math.round((nimScore * 0.30 + nplScore * 0.25 + custScore * 0.20 + roaScore * 0.15 + conductScore * 0.10) * 1000);
    }

    getPerformanceSummary(history) {
      if (!history.length) return {};
      var lastRecord = history[history.length - 1];
      var results = lastRecord.results || {};
      var ds = window.mySimulation.state.domainState;
      var totalProfit = ds.totalProfit;
      var finalNIM = ds.nim;
      var finalNPL = ds.nplRatio;
      var finalROA = ds.roa;
      var finalConduct = ds.conductRiskScore;
      var customerGrowth = ((ds.customers - 12800) / 12800) * 100;
      var composite = this._composite(ds);
      var performance = this._t('perf_needs');
      if (composite >= 700) performance = this._t('perf_excellent');
      else if (composite >= 550) performance = this._t('perf_good');
      else if (composite >= 400) performance = this._t('perf_developing');
      var insights = [];
      insights.push(finalNIM >= 5.5 ? this._t('insight_nim_good') : this._t('insight_nim_bad'));
      insights.push(finalNPL <= 4.0 ? this._t('insight_npl_good') : this._t('insight_npl_bad'));
      insights.push(customerGrowth >= 15 ? this._t('insight_cust_good') : this._t('insight_cust_bad'));
      insights.push(finalConduct >= 85 ? this._t('insight_conduct_good') : this._t('insight_conduct_bad'));
      return {
        compositeScore: composite, totalProfit: Math.round(totalProfit),
        finalNIM: finalNIM, finalNPL: finalNPL, finalROA: finalROA,
        conductRiskScore: finalConduct, customerGrowth: Math.round(customerGrowth * 10) / 10,
        performance: performance, insights: insights
      };
    }

    getHint(state, results) {
      if (!results) return null;
      if (results.nim < 4.5) return window.mySimulation.t('hint_nim_low');
      if (results.nplRatio > 6) return window.mySimulation.t('hint_npl_high');
      if (results.netIncome < 0) return window.mySimulation.t('hint_loss');
      if (state.domainState.loanPortfolio > state.domainState.depositBook * 1.5) return window.mySimulation.t('hint_funding_gap');
      if (state.decisions.loanIncentiveWeight > 70) return window.mySimulation.t('hint_conduct_risk');
      return null;
    }

