    _updateBriefing(state) {
      var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
      var round = this.ROUNDS[idx];
      var titleEl = document.getElementById('briefingTitle');
      if (titleEl) titleEl.textContent = window.mySimulation ? window.mySimulation.t(round.titleKey) : '';
      var textEl = document.getElementById('briefingText');
      if (textEl) textEl.textContent = window.mySimulation ? window.mySimulation.t(round.descKey) : '';
      var evtEl = document.getElementById('eventLogDisplay');
      if (evtEl && window.mySimulation && window.mySimulation.state) {
        evtEl.innerHTML = window.mySimulation.state.domainState.eventLog || '';
      }
    }

    _toggleRound3Panel(state) {
      var panel = document.getElementById('round3Panel');
      if (panel) { panel.style.display = (state.currentPeriod || 1) >= 3 ? 'block' : 'none'; }
    }

    _updateAdvisorTotal() {
      var la = document.getElementById('loanAdvisorsInput');
      var da = document.getElementById('depositAdvisorsInput');
      var cs = document.getElementById('crossSellAdvisorsInput');
      var cm = document.getElementById('creditMonitorInput');
      var total = (parseInt(la ? la.value : 0) || 0) + (parseInt(da ? da.value : 0) || 0) + (parseInt(cs ? cs.value : 0) || 0) + (parseInt(cm ? cm.value : 0) || 0);
      var display = document.getElementById('advisorTotal');
      if (display) { display.textContent = total; display.style.color = total === 8 ? '#27ae60' : '#e74c3c'; }
    }
